import{_ as e,o as a,c as l,a5 as d}from"./chunks/framework.D47SInms.js";const g=JSON.parse('{"title":"ROS 2 Service Reference","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"software/sdk/ros/services.md","filePath":"software/sdk/ros/services.md","lastUpdated":1791600043000}'),o={name:"software/sdk/ros/services.md"};function s(r,t,i,n,c,h){return a(),l("div",null,[...t[0]||(t[0]=[d('<h1 id="ros-2-service-reference" tabindex="-1">ROS 2 Service Reference <a class="header-anchor" href="#ros-2-service-reference" aria-label="Permalink to &quot;ROS 2 Service Reference&quot;">​</a></h1><p>Reference of the ROS 2 services the robot&#39;s onboard software exposes over CycloneDDS.</p><p>Like the <a href="/RBQ/nightly/software/sdk/ros/topics.html">topics</a>, the services need no driver node. Each robot process serves them directly over ROS 2-compatible DDS, so <code>ros2 service list</code> and <code>ros2 service call</code> work as soon as the process is running. Use the same <code>RMW_IMPLEMENTATION=rmw_cyclonedds_cpp</code> and network interface as for the topics (see <a href="/RBQ/nightly/software/sdk/ros/network.html">Network &amp; DDS</a>).</p><p>All services use the two standard <code>rcl_interfaces</code> types, so no extra workspace is needed:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Type</th><th style="text-align:left;">Used by</th></tr></thead><tbody><tr><td style="text-align:left;"><code>rcl_interfaces/srv/SetParameters</code></td><td style="text-align:left;"><code>set_param</code> — set values; <code>set_service</code> — run actions and switch features</td></tr><tr><td style="text-align:left;"><code>rcl_interfaces/srv/GetParameters</code></td><td style="text-align:left;"><code>get_param</code> — read values back</td></tr></tbody></table><h2 id="rules" tabindex="-1">Request and response rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Request and response rules {#rules}&quot;">​</a></h2><ul><li><strong>One result per parameter.</strong> <code>SetParameters</code> returns one <code>results[i]</code> per <code>parameters[i]</code>, in the same order. A parameter fails on its own — the others in the same request still apply.</li><li><strong>Failure reason.</strong> A failed entry has <code>successful: false</code> and a short English <code>reason</code> (for example <code>unknown parameter</code>, <code>expects number</code>). A successful entry has an empty <code>reason</code>.</li><li><strong>Up to 64 parameters per request.</strong> A larger request is rejected as a whole: every <code>set_*</code> entry fails with <code>too many parameters (max 64)</code>, and every <code>get_param</code> value comes back unset.</li><li><strong>Value type.</strong> Set <code>value.type</code> explicitly (<code>1</code>=bool, <code>2</code>=integer, <code>3</code>=double, <code>4</code>=string). If you leave it at <code>0</code>, the robot uses the one value field you filled in. A zero value (<code>0</code>, <code>0.0</code>, empty string) cannot be detected that way, so always set the type when sending zero.</li><li><strong>Unknown names in <code>get_param</code></strong> come back with <code>type: 0</code> (not set).</li><li><strong><code>set_service</code> takes bool values</strong> unless the name says otherwise (<code>gait</code>, <code>stream_live</code>). Entries marked <em>true only</em> fail with <code>true only</code> when sent <code>false</code>.</li></ul><table tabindex="0"><thead><tr><th style="text-align:left;">Service</th><th style="text-align:left;">Process</th><th style="text-align:left;">Available when</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="#motion"><code>/rbq/motion/*</code></a></td><td style="text-align:left;"><code>Network</code></td><td style="text-align:left;">Robot software is running</td></tr><tr><td style="text-align:left;"><a href="#vision"><code>/rbq/vision/*</code></a></td><td style="text-align:left;"><code>Streamer</code></td><td style="text-align:left;">Vision software is running</td></tr><tr><td style="text-align:left;"><a href="#camera"><code>/rbq/camera/*</code></a></td><td style="text-align:left;"><code>HAL</code></td><td style="text-align:left;">Vision software is running</td></tr><tr><td style="text-align:left;"><a href="#ptz"><code>/rbq/ptz/*</code></a></td><td style="text-align:left;"><code>Ptz</code></td><td style="text-align:left;">The <a href="/RBQ/nightly/manual/related-products/ptz-camera.html">PTZ camera payload</a> is installed</td></tr></tbody></table><h2 id="motion" tabindex="-1">Motion <a class="header-anchor" href="#motion" aria-label="Permalink to &quot;Motion {#motion}&quot;">​</a></h2><h3 id="rbq-motion-set-param" tabindex="-1"><code>/rbq/motion/set_param</code> <a class="header-anchor" href="#rbq-motion-set-param" aria-label="Permalink to &quot;`/rbq/motion/set_param`&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;">Type</td><td style="text-align:left;"><code>rcl_interfaces/srv/SetParameters</code></td></tr><tr><td style="text-align:left;">Description</td><td style="text-align:left;">Set payload, walking, and docking parameters. All values are numbers (integer or double).</td></tr></tbody></table><table tabindex="0"><thead><tr><th style="text-align:left;">Name</th><th style="text-align:left;">Unit</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>payload.mass</code></td><td style="text-align:left;">kg</td><td style="text-align:left;">Mass of the extra payload, used for CoM compensation</td></tr><tr><td style="text-align:left;"><code>payload.com_x</code> / <code>payload.com_y</code> / <code>payload.com_z</code></td><td style="text-align:left;">m</td><td style="text-align:left;">Payload centre of mass, body frame</td></tr><tr><td style="text-align:left;"><code>dynamics.max_speed</code></td><td style="text-align:left;">m/s</td><td style="text-align:left;">Upper limit of the walking speed</td></tr><tr><td style="text-align:left;"><code>dynamics.body_height</code></td><td style="text-align:left;">m</td><td style="text-align:left;">Standing height offset relative to the default</td></tr><tr><td style="text-align:left;"><code>dynamics.body_tilt</code></td><td style="text-align:left;">deg</td><td style="text-align:left;">Fixed body pitch while walking</td></tr><tr><td style="text-align:left;"><code>dock.offset_x</code> / <code>dock.offset_y</code></td><td style="text-align:left;">m</td><td style="text-align:left;">Docking target offset</td></tr><tr><td style="text-align:left;"><code>dock.count_req</code></td><td style="text-align:left;">—</td><td style="text-align:left;">Marker detection attempts before docking</td></tr><tr><td style="text-align:left;"><code>dock.count_try</code></td><td style="text-align:left;">—</td><td style="text-align:left;">Docking failures allowed before giving up</td></tr></tbody></table><p>The <code>dynamics.*</code> ranges are those of the app&#39;s <a href="/RBQ/nightly/manual/gui/motion-commands.html#drive-parameters">Drive parameters</a>. A <code>payload.*</code> value outside the payload limits fails with <code>reason: validation_error</code>. The CoM limits are |x| ≤ 0.5 m, |y| ≤ 0.3 m, |z| ≤ 0.4 m; the mass limit depends on the robot model.</p><div class="warning custom-block"><p class="custom-block-title">Set <code>dynamics.max_speed</code> first</p><p>The robot applies the three <code>dynamics.*</code> values together. Until <code>dynamics.max_speed</code> has been set once, <code>body_height</code> and <code>body_tilt</code> fail with <code>dynamics.max_speed not set yet - set it first</code>. Send all three in one request to be safe. The stored values reset when the robot&#39;s software restarts.</p></div><p><code>payload.*</code> sets the first custom payload slot.</p><h3 id="rbq-motion-get-param" tabindex="-1"><code>/rbq/motion/get_param</code> <a class="header-anchor" href="#rbq-motion-get-param" aria-label="Permalink to &quot;`/rbq/motion/get_param`&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;">Type</td><td style="text-align:left;"><code>rcl_interfaces/srv/GetParameters</code></td></tr><tr><td style="text-align:left;">Description</td><td style="text-align:left;">Read back the <code>set_param</code> names above. Values come back as doubles (<code>type: 3</code>).</td></tr></tbody></table><p><code>dynamics.max_speed</code> is unset until it has been set through <code>set_param</code>.</p><h3 id="rbq-motion-set-service" tabindex="-1"><code>/rbq/motion/set_service</code> <a class="header-anchor" href="#rbq-motion-set-service" aria-label="Permalink to &quot;`/rbq/motion/set_service`&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;">Type</td><td style="text-align:left;"><code>rcl_interfaces/srv/SetParameters</code></td></tr><tr><td style="text-align:left;">Description</td><td style="text-align:left;">Run motion actions and switch modes.</td></tr></tbody></table><table tabindex="0"><thead><tr><th style="text-align:left;">Name</th><th style="text-align:left;">Value</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>estop</code></td><td style="text-align:left;">bool, <em>true only</em></td><td style="text-align:left;">Emergency stop — every joint goes to high damping. <strong>The robot collapses.</strong> Same as <a href="/RBQ/nightly/software/sdk/ros/topics.html#rbq-cmd-emergency"><code>/rbq/cmd/emergency</code></a></td></tr><tr><td style="text-align:left;"><code>auto_start</code></td><td style="text-align:left;">bool, <em>true only</em></td><td style="text-align:left;">CAN check → Find Home → Control Start. Same as <a href="/RBQ/nightly/software/sdk/ros/topics.html#rbq-cmd-auto-start"><code>/rbq/cmd/auto_start</code></a></td></tr><tr><td style="text-align:left;"><code>control_mode</code></td><td style="text-align:left;">bool</td><td style="text-align:left;"><code>true</code> → HighLevel Command mode, <code>false</code> → joystick mode. Same as <a href="/RBQ/nightly/software/sdk/ros/topics.html#rbq-cmd-switch-control-mode"><code>/rbq/cmd/switch_control_mode</code></a></td></tr><tr><td style="text-align:left;"><code>power_ch&lt;N&gt;</code></td><td style="text-align:left;">bool</td><td style="text-align:left;">Turn PDU power port <code>N</code> on or off, for <code>N</code> from <code>0</code> to <code>31</code>. Port numbers are listed under <a href="/RBQ/nightly/software/sdk/ros/topics.html#power-control">Power Control</a></td></tr><tr><td style="text-align:left;"><code>gait</code></td><td style="text-align:left;">integer or string</td><td style="text-align:left;">Switch gait. Integer: a gait id from the <a href="/RBQ/nightly/software/sdk/ros/reference.html#gait-state-ids">Gait State IDs</a>. String: one of the names below</td></tr></tbody></table><p>Gait names accepted by <code>gait</code> (case-insensitive): <code>sitting</code>, <code>standing</code>, <code>aiming</code>, <code>trotting</code>, <code>trot_stairs</code>, <code>waving</code>, <code>trot_running</code>, <code>docking</code>, <code>rl_trot</code>, <code>rl_front_walk</code>, <code>rl_left_walk</code>, <code>rl_right_walk</code>, <code>rl_bound</code>, <code>rl_pace</code>, <code>rl_pronk</code>, <code>rl_3leg_hr</code>, <code>rl_trot_vision</code>, <code>rl_trot_run</code>, <code>rl_silent</code>, <code>rl_trot_vision_slow</code>, <code>rl_walk</code>, <code>rl_walk_vision</code>. Another id or name fails with <code>unknown gait id</code> / <code>unknown gait name</code>.</p><div class="danger custom-block"><p class="custom-block-title">DANGER</p><p><code>estop</code> cuts joint torque at once and the robot falls. Sit the robot down first when testing.</p></div><p><strong>Examples:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Walking parameters — send all three together</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> call</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /rbq/motion/set_param</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rcl_interfaces/srv/SetParameters</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;{parameters: [</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    {name: &#39;dynamics.max_speed&#39;,   value: {type: 3, double_value: 1.0}},</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    {name: &#39;dynamics.body_height&#39;, value: {type: 3, double_value: 0.0}},</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    {name: &#39;dynamics.body_tilt&#39;,   value: {type: 3, double_value: 0.0}}]}&quot;</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Read the payload mass</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> call</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /rbq/motion/get_param</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rcl_interfaces/srv/GetParameters</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;{names: [&#39;payload.mass&#39;]}&quot;</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Switch to standing by name</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> call</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /rbq/motion/set_service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rcl_interfaces/srv/SetParameters</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;{parameters: [{name: &#39;gait&#39;, value: {type: 4, string_value: &#39;standing&#39;}}]}&quot;</span></span></code></pre></div><h2 id="vision" tabindex="-1">Vision <a class="header-anchor" href="#vision" aria-label="Permalink to &quot;Vision {#vision}&quot;">​</a></h2><h3 id="rbq-vision-set-param-·-rbq-vision-get-param" tabindex="-1"><code>/rbq/vision/set_param</code> · <code>/rbq/vision/get_param</code> <a class="header-anchor" href="#rbq-vision-set-param-·-rbq-vision-get-param" aria-label="Permalink to &quot;`/rbq/vision/set_param` · `/rbq/vision/get_param`&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;">Type</td><td style="text-align:left;"><code>rcl_interfaces/srv/SetParameters</code> · <code>rcl_interfaces/srv/GetParameters</code></td></tr><tr><td style="text-align:left;">Description</td><td style="text-align:left;">WebRTC video stream settings. Changes are kept across restarts.</td></tr></tbody></table><table tabindex="0"><thead><tr><th style="text-align:left;">Name</th><th style="text-align:left;">Value</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>webrtc.width</code> / <code>webrtc.height</code></td><td style="text-align:left;">integer, <code>16</code>–<code>7680</code></td><td style="text-align:left;">Stream resolution in pixels. Setting one keeps the other</td></tr><tr><td style="text-align:left;"><code>webrtc.preset</code></td><td style="text-align:left;">string</td><td style="text-align:left;">x264 encoder preset: <code>ultrafast</code>, <code>superfast</code>, <code>veryfast</code>, <code>faster</code>, <code>fast</code>, <code>medium</code>, <code>slow</code>, <code>slower</code>, <code>veryslow</code>, <code>placebo</code></td></tr></tbody></table><h3 id="rbq-vision-set-service" tabindex="-1"><code>/rbq/vision/set_service</code> <a class="header-anchor" href="#rbq-vision-set-service" aria-label="Permalink to &quot;`/rbq/vision/set_service`&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;">Type</td><td style="text-align:left;"><code>rcl_interfaces/srv/SetParameters</code></td></tr><tr><td style="text-align:left;">Description</td><td style="text-align:left;">Switch vision features and the live view.</td></tr></tbody></table><table tabindex="0"><thead><tr><th style="text-align:left;">Name</th><th style="text-align:left;">Value</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>stream_live</code></td><td style="text-align:left;">integer</td><td style="text-align:left;">Select the live view by id — <code>0</code> = none, <code>1</code> front, <code>2</code> rear, <code>3</code> left, <code>4</code> right, <code>11</code> stacked, <code>12</code> panorama, <code>13</code> stairs, <code>14</code> side by side, <code>15</code> dock</td></tr><tr><td style="text-align:left;"><code>face_detect</code></td><td style="text-align:left;">bool</td><td style="text-align:left;">Face detection overlay</td></tr><tr><td style="text-align:left;"><code>point2go</code></td><td style="text-align:left;">bool</td><td style="text-align:left;">Point-to-go overlay</td></tr><tr><td style="text-align:left;"><code>guide</code></td><td style="text-align:left;">bool</td><td style="text-align:left;">Guide overlay</td></tr><tr><td style="text-align:left;"><code>day</code></td><td style="text-align:left;">bool</td><td style="text-align:left;"><code>true</code> → day mode, <code>false</code> → night (IR) mode</td></tr><tr><td style="text-align:left;"><code>heightmap.stairs</code></td><td style="text-align:left;">bool</td><td style="text-align:left;">Stairs detection in the height map</td></tr><tr><td style="text-align:left;"><code>heightmap.edge</code></td><td style="text-align:left;">bool</td><td style="text-align:left;">Edge detection in the height map</td></tr><tr><td style="text-align:left;"><code>heightmap.align</code></td><td style="text-align:left;">bool</td><td style="text-align:left;">Align the height map to the body yaw</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TIP</p><p><code>stream_live: 0</code> (no view) is accepted but ignored while other viewers are watching the stream.</p></div><h2 id="camera" tabindex="-1">Camera <a class="header-anchor" href="#camera" aria-label="Permalink to &quot;Camera {#camera}&quot;">​</a></h2><h3 id="rbq-camera-set-param-·-rbq-camera-get-param" tabindex="-1"><code>/rbq/camera/set_param</code> · <code>/rbq/camera/get_param</code> <a class="header-anchor" href="#rbq-camera-set-param-·-rbq-camera-get-param" aria-label="Permalink to &quot;`/rbq/camera/set_param` · `/rbq/camera/get_param`&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;">Type</td><td style="text-align:left;"><code>rcl_interfaces/srv/SetParameters</code> · <code>rcl_interfaces/srv/GetParameters</code></td></tr><tr><td style="text-align:left;">Description</td><td style="text-align:left;">Read and write the camera configuration as <code>&lt;SECTION&gt;.&lt;key&gt;</code> — for example <code>MAIN.RS_PRESET_HIGH_DENSITY</code>.</td></tr></tbody></table><ul><li><code>set_param</code> changes only keys that already exist; a typo fails with <code>unknown section</code> or <code>unknown key</code>. Any scalar value is accepted and stored as text. The camera configuration reloads after a successful change.</li><li><code>get_param</code> returns the stored text (<code>type: 4</code>), or unset if the key does not exist.</li></ul><h3 id="rbq-camera-set-service" tabindex="-1"><code>/rbq/camera/set_service</code> <a class="header-anchor" href="#rbq-camera-set-service" aria-label="Permalink to &quot;`/rbq/camera/set_service`&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;">Type</td><td style="text-align:left;"><code>rcl_interfaces/srv/SetParameters</code></td></tr><tr><td style="text-align:left;">Description</td><td style="text-align:left;">Camera actions.</td></tr></tbody></table><table tabindex="0"><thead><tr><th style="text-align:left;">Name</th><th style="text-align:left;">Value</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>ir_projector</code></td><td style="text-align:left;">bool</td><td style="text-align:left;">IR projector of every depth camera on or off</td></tr><tr><td style="text-align:left;"><code>reload_config</code></td><td style="text-align:left;">bool, <em>true only</em></td><td style="text-align:left;">Reload the camera configuration</td></tr><tr><td style="text-align:left;"><code>sensor_&lt;N&gt;.enabled</code></td><td style="text-align:left;">bool</td><td style="text-align:left;">Open (<code>true</code>) or close (<code>false</code>) camera sensor <code>N</code>. Sensor ids are listed under <a href="/RBQ/nightly/software/sdk/ros/topics.html#vision-camera-sensors">Vision — Camera Sensors</a></td></tr></tbody></table><h2 id="ptz" tabindex="-1">PTZ <a class="header-anchor" href="#ptz" aria-label="Permalink to &quot;PTZ {#ptz}&quot;">​</a></h2><h3 id="rbq-ptz-set-param" tabindex="-1"><code>/rbq/ptz/set_param</code> <a class="header-anchor" href="#rbq-ptz-set-param" aria-label="Permalink to &quot;`/rbq/ptz/set_param`&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;">Type</td><td style="text-align:left;"><code>rcl_interfaces/srv/SetParameters</code></td></tr><tr><td style="text-align:left;">Description</td><td style="text-align:left;">PTZ position and speed. All values are numbers.</td></tr></tbody></table><table tabindex="0"><thead><tr><th style="text-align:left;">Name</th><th style="text-align:left;">Unit</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>pan</code> / <code>tilt</code></td><td style="text-align:left;">rad</td><td style="text-align:left;">Target angle, same ranges as <a href="/RBQ/nightly/software/sdk/ros/topics.html#vision-ptz-camera"><code>/rbq/cmd/ptz</code></a></td></tr><tr><td style="text-align:left;"><code>zoom</code></td><td style="text-align:left;">×</td><td style="text-align:left;">Target zoom, same range as <code>/rbq/cmd/ptz</code></td></tr><tr><td style="text-align:left;"><code>pan_vel</code> / <code>tilt_vel</code></td><td style="text-align:left;">deg/s</td><td style="text-align:left;">Turn at this speed</td></tr><tr><td style="text-align:left;"><code>zoom_vel</code></td><td style="text-align:left;">—</td><td style="text-align:left;">Zoom continuously at this rate</td></tr></tbody></table><p>Unlike <code>/rbq/cmd/ptz</code>, each name applies on its own — setting <code>pan</code> leaves tilt and zoom where they are.</p><p>There is no <code>get_param</code> for the PTZ — read the current position from <a href="/RBQ/nightly/software/sdk/ros/topics.html#rbq-ptz"><code>/rbq/ptz</code></a>.</p><h3 id="rbq-ptz-set-service" tabindex="-1"><code>/rbq/ptz/set_service</code> <a class="header-anchor" href="#rbq-ptz-set-service" aria-label="Permalink to &quot;`/rbq/ptz/set_service`&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;">Type</td><td style="text-align:left;"><code>rcl_interfaces/srv/SetParameters</code></td></tr><tr><td style="text-align:left;">Description</td><td style="text-align:left;">PTZ actions. Both names act only when sent <code>true</code>.</td></tr></tbody></table><table tabindex="0"><thead><tr><th style="text-align:left;">Name</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>return_center</code></td><td style="text-align:left;">Move pan and tilt back to centre and zoom to 1×</td></tr><tr><td style="text-align:left;"><code>stop</code></td><td style="text-align:left;">Stop pan and tilt movement</td></tr></tbody></table>',49)])])}const p=e(o,[["render",s]]);export{g as __pageData,p as default};
